  assert.equal(findEvidenceAc(body, label), null);
  assert.equal(findAcSectionCheckbox(body, label), null);
  assert.throws(() => stampAcEvidenceMarker(body, label, fixtureEvidence), /no evidence-bearing AC line/);
});
